select repair_news_content('8927cbe3-6b2f-4d00-b9ac-bdc60bc3a764'::uuid,'{"source_excerpt":"דיווח וואלה ספורט עוסק באכזבה בבאר שבע אחרי ההפסד באלקמאר, בטעויות שהכריעו את המשחק ובחשש לפציעתו של עידן נחמיאס.","source_published_at":"2026-10-16T04:47:00.000Z"}'::jsonb);
update news_items set summary='דיווח וואלה ספורט עוסק באכזבה בבאר שבע אחרי ההפסד באלקמאר, בטעויות שהכריעו את המשחק ובחשש לפציעתו של עידן נחמיאס.',body='על פי דיווחו של יניב טוכמן בוואלה ספורט מ־16 באוקטובר, הפועל באר שבע יצאה מהמשחק באלקמאר בתחושה שהייתה יכולה להשיג לפחות נקודה. אמנקווה פורסון השווה, ובהמשך החמיץ ג׳בון איסט הזדמנות להעלות את האורחת ליתרון. עבירה של ג׳יבריל דיופ הובילה לבדיקת VAR ולפנדל שהכריע את המפגש לטובת ההולנדים. הכתבה מייחסת לשגיאות ההגנה תפקיד בשני השערים שספגה באר שבע.

עוד דווח על חשש לפגיעה בשריר הירך האחורי של עידן נחמיאס. האפשרות שייעדר מספר שבועות הוצגה כהערכה, ולא כאבחנה סופית. לקראת המשחק מול הפועל ירושלים הועלתה האפשרות שמיגל ויטור ואיתי רוטמן יפתחו יחד. למרות האכזבה, במועדון הביעו ביטחון ביכולתם לצבור נקודות בהמשך הליגה האירופית.',source_name='וואלה ספורט',source_published_at='2026-10-16T04:47:00.000Z'::timestamptz,content_kind='original' where id='8927cbe3-6b2f-4d00-b9ac-bdc60bc3a764'::uuid and source_url='https://sports.walla.co.il/item/3872419' and content_kind='source_excerpt';
select repair_news_content('08096893-e388-49ba-a050-90c5ca4ef01b'::uuid,'{"source_excerpt":"הפועל תל אביב פרסמה הכנה למשחק הבית מול עירוני טבריה: שעת פתיחה, תמונת הטבלה, צוות השיפוט והמאזן ההיסטורי בין המועדונים.","source_published_at":"2026-10-17T02:05:52.000Z"}'::jsonb);
update news_items set summary='הפועל תל אביב פרסמה הכנה למשחק הבית מול עירוני טבריה: שעת פתיחה, תמונת הטבלה, צוות השיפוט והמאזן ההיסטורי בין המועדונים.',body='בהכנה הרשמית שפרסמה הפועל תל אביב ב־17 באוקטובר נקבע משחק הבית מול עירוני טבריה לאותו יום בבלומפילד, בשעה 18:45, במסגרת המחזור השביעי. לפי המועדון, האדומים הגיעו למחזור במקום השלישי עם 13 נקודות, אחרי ניצחון החוץ על קריית שמונה. טבריה הוצגה כאחרונה בטבלה עם נקודה אחת לאחר הפחתה של שש נקודות.

בפרסום נמסר כי עומר בירן ינהל את המשחק והשידור מתוכנן בספורט 4 HD. לצד המידע המעשי סקר המועדון את המפגשים הקודמים: הפועל ניצחה בשני משחקי הליגה בעונה הקודמת, בכל אחד מהם כבשה פעמיים ולא ספגה. המאזן ההיסטורי המורחב המובא בכתבה כולל גם את הפועל טבריה בעבר, ולכן אינו מתייחס רק לעירוני טבריה הנוכחית. הנתונים משקפים את ההכנה שפורסמה לפני המשחק.',source_name='הפועל תל אביב — האתר הרשמי',source_published_at='2026-10-17T02:05:52.000Z'::timestamptz,content_kind='original' where id='08096893-e388-49ba-a050-90c5ca4ef01b'::uuid and source_url='https://www.htafc.co.il/%d7%9e%d7%90%d7%a8%d7%97%d7%99%d7%9d-%d7%90%d7%aa-%d7%98%d7%91%d7%a8%d7%99%d7%94-%d7%9b%d7%9c-%d7%94%d7%9e%d7%99%d7%93%d7%a2-%d7%9c%d7%a7%d7%a8%d7%90%d7%aa-%d7%94%d7%9e%d7%a9%d7%97%d7%a7/' and content_kind='source_excerpt';
